<body>
  <main>
    <h1>Notification Preferences</h1>
    <p class="intro-text">Customize how you want to stay updated with important information.</p>

    <form id="notificationForm" novalidate>
      <div class="form-field">
        <fieldset aria-describedby="notification-help">
          <legend>
            How do you prefer to receive notifications?
            <span class="required-marker" aria-hidden="true">*</span>
          </legend>
          <p id="notification-help" class="field-description">
            Select your preferred communication method.
          </p>

          <div class="radio-options">
            <div class="radio-option">
              <input
                id="notif-email"
                type="radio"
                name="notification-preference"
                value="email"
                required
              >
              <label for="notif-email">Email</label>
            </div>

            <div class="radio-option">
              <input
                id="notif-sms"
                type="radio"
                name="notification-preference"
                value="sms"
                required
              >
              <label for="notif-sms">SMS</label>
            </div>

            <div class="radio-option">
              <input
                id="notif-push"
                type="radio"
                name="notification-preference"
                value="push"
                required
              >
              <label for="notif-push">Push Notifications</label>
            </div>
          </div>
        </fieldset>
      </div>

      <button type="submit">Save Preferences</button>

      <div id="successMessage" class="success-message" role="status" aria-live="polite">
        ✓ Your notification preferences have been saved.
      </div>
    </form>
  </main>

  <script>
    const form = document.getElementById('notificationForm');
    const successMessage = document.getElementById('successMessage');

    form.addEventListener('submit', (e) => {
      e.preventDefault();

      const selectedOption = document.querySelector('input[name="notification-preference"]:checked');

      if (selectedOption) {
        console.log('Selected notification preference:', selectedOption.value);

        successMessage.classList.add('show');
        setTimeout(() => {
          successMessage.classList.remove('show');
        }, 4000);
      }
    });
  </script>
</body>
</html>
