const axeCore = require('axe-core');
const fs = require('fs');
const path = require('path');

async function runA11yTests() {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const htmlFile = path.join(__dirname, 'index.html');
  const htmlContent = fs.readFileSync(htmlFile, 'utf-8');

  await page.setContent(htmlContent, { waitUntil: 'load' });

  await page.addScriptTag({ path: '/tmp/axe.min.js' });

  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log('\n=== ACCESSIBILITY TEST RESULTS ===\n');

  if (wcag.length === 0 && bp.length === 0) {
    console.log('✓ PASS: No violations found\n');
    return 0;
