    wcag.forEach(v => {
      console.log(`\n  [${v.id}] - Impact: ${v.impact}`);
      console.log(`  Description: ${v.description}`);
      console.log(`  Affected elements: ${v.nodes.map(n => n.target).join(', ')}`);
      console.log(`  Help: ${v.help}`);
    });
  }

  if (bp.length > 0) {
    console.log(`\n⚠️  Best Practice Warnings (${bp.length}):`);
    bp.forEach(v => {
      console.log(`\n  [${v.id}]`);
      console.log(`  Affected elements: ${v.nodes.map(n => n.target).join(', ')}`);
    });
  }

  console.log('\n');
  return wcag.length > 0 ? 1 : 0;
}

runA11yTests().then(code => process.exit(code));
